The `buildReadback` function should be robust against missing or malformed `audit` or `validatorResult` objects to prevent throwing unhandled exceptions and crashing the script during closeout reporting. Adding defensive guards and safe defaults ensures graceful failure.

```suggestion
function buildReadback({ audit, validatorResult, paths }) {
  if (!isObject(audit) || !isObject(validatorResult)) {
    return '# Semantic KG Pilot Error Audit Readback\n\nError: Audit or validator result is missing or malformed.';
  }
  const summary = audit.summary ?? {};
  const boundary = audit.boundary ?? {};
  const errorTaxonomy = Array.isArray(audit.error_taxonomy) ? audit.error_taxonomy : [];
  const goNoGo = audit.go_no_go ?? {};
  const blockedReasons = Array.isArray(goNoGo.blocked_reasons) ? goNoGo.blocked_reasons : [];

  return [
    '# Semantic KG Pilot Error Audit Readback',
    '',
    `Generated at: ${audit.generated_at}`,
    `Issue: #${ISSUE}`,
